1	import * as THREE from 'three';
2	import { CONFIG } from '../config';
3	import { scene } from '../core/renderer';
4	import { weatherFx } from '../core/shared';
5	import { rng, lerp } from '../common/math';
6	import { createPeople, stepPeople, ppApplyKinds, ppFaceZ, type People, type Walker } from '../common/people';
7	import { ppAssignKinds } from '../common/people/kinds';
8	import { deckY } from '../bridges/dragon/profile';
9	
10	/* =====================================================================
11	   NGƯỜI ĐI BỘ CẦU RỒNG (spec G9, G10, §7) — hai lề 2,5 m, ngày và đêm như nhau, không nút bật/tắt.
12	   Dựng bằng rng(CONFIG.people.dragon.seed) riêng (không gọi rand()), sau mọi lệnh dựng dùng rand() trong main.ts.
13	   Người đứng sát lan can, mặt quay ra sông; phần headBias số người đứng ở đoạn gần đầu rồng (x > 150, phía Đông).
14	   Lớp 1 (không phản chiếu), không đổ bóng; ẩn cả nhóm khi camera xa hơn hideDistance; bão đóng cầu thì rời cầu dần như xe.
15	   ===================================================================== */
16	const D = CONFIG.people.dragon;
17	const CENTER = new THREE.Vector3(0, deckY(0), 0);
18	let dragon: People | null = null;
19	
20	export function buildDragonPeople(): void {
21	  const r = rng(D.seed), W = CONFIG.people.walk, hw = CONFIG.width / 2, zWalk = D.walkZ, list: Walker[] = [];   // tuyến đi giữa hàng cột đèn (|z| 17) và lan can
22	  const onDeck = (x: number) => deckY(x) + 0.25;   // mặt lát lề cao 0,25 m trên bản mặt cầu (deck.ts)
23	  for (let i = 0; i < D.n; i++) list.push({ x: lerp(-325, 325, r()), z: (r() < 0.5 ? -1 : 1) * zWalk, lo: -325, hi: 325, dir: r() < 0.5 ? -1 : 1, speed: lerp(W.speed[0], W.speed[1], r()), profile: onDeck });
24	  const infos = ppAssignKinds(D.n, D.seed + 1), nHead = Math.round(infos.filter((k) => k.kind === 'stand').length * D.headBias);
25	  let k = 0;
26	  ppApplyKinds(list, infos, (w) => {
27	    const s = Math.sign(w.z);
28	    w.z = s * (hw - 0.5); w.face = ppFaceZ(s);
29	    w.x = k++ < nHead ? lerp(150, D.standX, r()) : lerp(-D.standX, 150, r());   // headBias phần người đứng ở đoạn gần đầu rồng; chỉ trên phần cầu qua sông (một r() mỗi người như cũ)
30	  }, true);   // người đi cùng lệch ra phía lan can, không lấn vào hàng cột đèn
31	  dragon = createPeople({ group: scene, noReflect: [] }, list, 'dragon-people', r);
32	  dragon.group.traverse((o) => o.layers.set(1));
33	  /* Cắt theo khung nhìn: khối cầu cố định bao mọi chỗ người có thể tới trên cả mặt cầu (không computeBoundingSphere — sẽ co theo vị trí lúc gọi) */
34	  const box = new THREE.Box3(new THREE.Vector3(-326, CONFIG.roadY, -hw), new THREE.Vector3(326, deckY(0) + 2.5, hw));   // x ±(325 + 1) m, cao tới đỉnh nón / tay giơ trên đỉnh vồng
35	  dragon.mesh.boundingSphere = box.getBoundingSphere(new THREE.Sphere()); dragon.mesh.frustumCulled = true;
36	}
37	
38	export function updateDragonPeople(dt: number, elapsed: number, cam: THREE.Camera): void {
39	  if (!dragon) return;
40	  const near = cam.position.distanceTo(CENTER) < D.hideDistance;
41	  if (near) stepPeople(dragon, dt, elapsed, true);
42	  dragon.group.visible = near && weatherFx.clear < 1;   // bão đã dọn hết thì bỏ luôn lệnh vẽ
43	}
44	
45	/* Móc kiểm thử (tests/people-check.mjs): các hệ người tìm theo tên trong scene */
46	const PP_NAMES = ['ttl-people', 'sh-people', 'dragon-people'];
47	const ppFind = (name: string) => {
48	  const g = scene.getObjectByName(name), meshes: THREE.InstancedMesh[] = [];
49	  g?.traverse((o) => { if ((o as THREE.InstancedMesh).isInstancedMesh) meshes.push(o as THREE.InstancedMesh); });
50	  return { g, meshes, list: (g?.userData.people as People | undefined)?.list };
51	};
52	export const peopleTest = {
53	  /* visible = số instance có scale > 0 */
54	  systems(): { name: string; count: number; visible: number; meshes: number; material: string; materialName: string; verts: number; colors: number; shirtKinds: number; instAttrs: boolean; groupVisible: boolean }[] {
55	    return PP_NAMES.map((name) => {
56	      const { g, meshes } = ppFind(name), m = meshes[0];
57	      if (!m) return null;
58	      const a = m.instanceMatrix.array, c = m.instanceColor?.array, geo = m.geometry, shirts = new Set<string>();
59	      let visible = 0;
60	      for (let i = 0; i < m.count; i++) { if (Math.abs(a[i * 16]) + Math.abs(a[i * 16 + 1]) + Math.abs(a[i * 16 + 2]) > 1e-9) visible++; if (c) shirts.add(`${c[i * 3].toFixed(3)},${c[i * 3 + 1].toFixed(3)},${c[i * 3 + 2].toFixed(3)}`); }
61	      const inst = (n: string) => !!(geo.getAttribute(n) as THREE.InstancedBufferAttribute)?.isInstancedBufferAttribute;
62	      const mat = m.material as THREE.Material;
63	      return { name, count: m.count, visible, meshes: meshes.length, material: mat.uuid, materialName: mat.name, verts: geo.getAttribute('position').count, colors: c ? c.length / 3 : 0, shirtKinds: shirts.size, instAttrs: inst('aVar') && inst('aPants'), groupVisible: g.visible };
64	    }).filter(Boolean);
65	  },
66	  /* Vị trí cục bộ (trong nhóm cầu) từng người, cao độ mặt lề tại đó, kiểu, scale, trục đứng (y của trục Y), hướng mặt (+X của hình) */
67	  positions(name: string): { i: number; x: number; y: number; z: number; ground: number; kind: string; scale: number; upY: number; fwd: number[] }[] {
68	    const { meshes, list } = ppFind(name), m = meshes[0], M = new THREE.Matrix4(), p = new THREE.Vector3(), q = new THREE.Quaternion(), s = new THREE.Vector3(), up = new THREE.Vector3(), fwd = new THREE.Vector3();
69	    if (!m || !list) return [];
70	    return list.map((w, i) => {
71	      m.getMatrixAt(i, M); M.decompose(p, q, s);
72	      up.set(0, 1, 0).applyQuaternion(q); fwd.set(1, 0, 0).applyQuaternion(q);
73	      return { i, x: p.x, y: p.y, z: p.z, ground: w.profile(w.axis === 'z' ? w.z : w.x), kind: w.kind ?? 'walk', scale: s.x, upY: up.y, fwd: fwd.toArray() };
74	    });
75	  }
76	};
