1	/* ===== Dữ liệu đám đông người thật (D-032): đọc public/people/crowd.bin + crowd.jpg ===== */
2	/* Spec: docs/superpowers/specs/2026-11-12-dam-dong-nguoi-that-design.md §4; sinh bằng npm run gen:crowd (scripts/people/crowd.py).
3	   10 nhân vật Rocketbox (MIT) giản lược ≤ 1 600 tam giác, 22 xương, 2 xương mỗi đỉnh; chuyển động nướng thành ma trận xương.
4	   Hệ toạ độ của lưới: mét, +Y lên, mặt hướng +X, chân y = 0, tư thế nghỉ chữ T / chữ A (cần skin mới ra dáng đi).
5	
6	   Định dạng crowd.bin (little-endian), phiên bản 1:
7	     0   4 byte  'DNCR'
8	     4   u32     phiên bản (1)
9	     8   u32     J = số byte phần JSON (đệm dấu cách tới bội 4)
10	     12  J byte  JSON utf-8: { bones, boneNames, anim: { width, height, offset, bytes }, source,
11	                 chars: [{ id, child, female, height, verts, tris, hatVerts, hatTris, pos, nrm, uv, bones, w, idx,
12	                           clips: { walk|jog|idle|photo: { row, frames, fps, loop, speed } } }] }
13	                 pos … idx là offset byte (tính từ đầu khối nhị phân) của từng mảng.
14	     12+J        khối nhị phân, mỗi mảng bắt đầu ở bội 4:
15	                 pos f32 ×3, nrm f32 ×3, uv f32 ×2, bones u8 ×2, w f32 ×1, idx u16 ×3 mỗi tam giác.
16	                 Đỉnh 0..verts−1 và tam giác 0..tris−1 là người; hatVerts / hatTris nối tiếp là nón lá (index trỏ vào mảng
17	                 đỉnh chung, gắn cứng xương đầu: bones = [đầu, đầu], w = 1). Bản đội nón = toàn bộ mảng.
18	                 anim: u16 (half-float) RGBA, width = bones × 3 texel, mỗi hàng một khung; texel (b × 3 + j) = hàng j của
19	                 ma trận 3×4 xương b, đưa đỉnh từ tư thế nghỉ sang tư thế khung (cùng hệ toạ độ lưới):
20	                   p' = Σ_k w_k · (dot(T[b_k·3], p1), dot(T[b_k·3+1], p1), dot(T[b_k·3+2], p1)), p1 = (p, 1); pháp tuyến dùng .xyz.
21	   uv: toạ độ trong atlas crowd.jpg với v = 0 ở mép TRÊN của ảnh (texture.flipY = false, ImageBitmap không lật).
22	   Đoạn: walk / idle / photo 15 khung/giây, jog 30; loop = false (photo) thì giữ khung cuối. speed: m/s tự nhiên ở tỉ lệ 1
23	   khi phát đúng fps (0 với idle, photo). Trẻ em: không có bản nón (hat = null). */
24	import * as THREE from 'three';
25	import { CONFIG } from '../../config';
26	
27	export type CrowdClipName = 'walk' | 'jog' | 'idle' | 'photo';
28	export interface CrowdClip { row: number; frames: number; fps: number; loop: boolean; speed: number }   // row: hàng đầu của đoạn trong texture chuyển động; speed: m/s tự nhiên ở tỉ lệ 1 (0 với idle, photo)
29	export interface CrowdChar {
30	  id: string;            // tên Rocketbox
31	  child: boolean; female: boolean;
32	  height: number;        // m, ở tỉ lệ 1
33	  geometry: THREE.BufferGeometry;           // position (Float32 ×3), normal (×3), uv (×2, toạ độ trong atlas), aBones (Uint8 ×2), aW (Float32 ×1: trọng số xương thứ nhất), có index
34	  hat: THREE.BufferGeometry | null;         // cùng bộ attribute, thêm nón lá; null với trẻ em
35	  clips: Record<CrowdClipName, CrowdClip>;
36	}
37	export interface CrowdParsed { chars: CrowdChar[]; bones: number; animWidth: number; animHeight: number; animData: Uint16Array; maxVerts: number; maxIndices: number }   // animData: RGBA half-float, mỗi hàng một khung, 3 texel mỗi xương
38	export interface CrowdData extends CrowdParsed { anim: THREE.DataTexture; atlas: THREE.Texture }
39	
40	const MAGIC = 'DNCR', VERSION = 1;
41	const CLIP_NAMES: CrowdClipName[] = ['walk', 'jog', 'idle', 'photo'];
42	
43	/* ===== Đọc tệp (thuần: không DOM, không fetch; chạy được trong node) ===== */
44	export function crowdParse(buf: ArrayBuffer): CrowdParsed {
45	  if (buf.byteLength < 12) throw new Error('crowd.bin: tệp quá ngắn');
46	  const head = new Uint8Array(buf, 0, 4), dv = new DataView(buf);
47	  if (String.fromCharCode(...head) !== MAGIC) throw new Error('crowd.bin: sai magic');
48	  const ver = dv.getUint32(4, true); if (ver !== VERSION) throw new Error(`crowd.bin: phiên bản ${ver} (cần ${VERSION})`);
49	  const J = dv.getUint32(8, true); if (12 + J > buf.byteLength || J % 4) throw new Error('crowd.bin: phần JSON hỏng');
50	  const meta = JSON.parse(new TextDecoder().decode(new Uint8Array(buf, 12, J)));
51	  const base = 12 + J;
52	  const view = <T>(C: { new (b: ArrayBuffer, o: number, n: number): T; BYTES_PER_ELEMENT: number }, off: number, n: number): T => {
53	    if (off % C.BYTES_PER_ELEMENT || base + off + n * C.BYTES_PER_ELEMENT > buf.byteLength) throw new Error('crowd.bin: mảng vượt tệp');
54	    return new C(buf, base + off, n);
55	  };
56	  const bones: number = meta.bones;
57	  let maxVerts = 0, maxIndices = 0;
58	  const chars: CrowdChar[] = meta.chars.map((c) => {
59	    const nv = c.verts + c.hatVerts, ni = (c.tris + c.hatTris) * 3;
60	    const pos = view(Float32Array, c.pos, nv * 3), nrm = view(Float32Array, c.nrm, nv * 3), uv = view(Float32Array, c.uv, nv * 2);
61	    const bi = view(Uint8Array, c.bones, nv * 2), w = view(Float32Array, c.w, nv), idx = view(Uint16Array, c.idx, ni);
62	    const geo = (v: number, i: number): THREE.BufferGeometry => {
63	      const g = new THREE.BufferGeometry();
64	      g.setAttribute('position', new THREE.BufferAttribute(pos.subarray(0, v * 3), 3));
65	      g.setAttribute('normal', new THREE.BufferAttribute(nrm.subarray(0, v * 3), 3));
66	      g.setAttribute('uv', new THREE.BufferAttribute(uv.subarray(0, v * 2), 2));
67	      g.setAttribute('aBones', new THREE.BufferAttribute(bi.subarray(0, v * 2), 2));
68	      g.setAttribute('aW', new THREE.BufferAttribute(w.subarray(0, v), 1));
69	      g.setIndex(new THREE.BufferAttribute(idx.subarray(0, i), 1));
70	      g.computeBoundingBox(); g.computeBoundingSphere();
71	      maxVerts = Math.max(maxVerts, v); maxIndices = Math.max(maxIndices, i);
72	      return g;
73	    };
74	    const clips = {} as Record<CrowdClipName, CrowdClip>;
75	    for (const n of CLIP_NAMES) {
76	      const k = c.clips?.[n]; if (!k) throw new Error(`crowd.bin: ${c.id} thiếu đoạn ${n}`);
77	      clips[n] = { row: k.row, frames: k.frames, fps: k.fps, loop: !!k.loop, speed: k.speed };
78	    }
79	    return { id: c.id, child: !!c.child, female: !!c.female, height: c.height, geometry: geo(c.verts, c.tris * 3), hat: c.hatVerts > 0 ? geo(nv, ni) : null, clips };
80	  });
81	  const a = meta.anim;
82	  if (a.width !== bones * 3 || a.bytes !== a.width * a.height * 8) throw new Error('crowd.bin: kích thước texture chuyển động sai');
83	  const animData = view(Uint16Array, a.offset, a.width * a.height * 4);
84	  return { chars, bones, animWidth: a.width, animHeight: a.height, animData, maxVerts, maxIndices };
85	}
86	
87	/* ===== Tải trong trình duyệt ===== */
88	let loaded: CrowdData | null = null;
89	let pending: Promise<CrowdData | null> | null = null;
90	
91	// Kết quả của lần crowdLoad đã xong (null nếu chưa xong, lỗi, hoặc ?crowd=off)
92	export function crowdGet(): CrowdData | null { return loaded; }
93	
94	// Tải bin + jpg theo BASE_URL, tối đa CONFIG.people.crowd.loadTimeoutMs; lỗi bất kỳ → console.warn một lần, trả null.
95	// ?crowd=off → null ngay, không gửi yêu cầu nào. Gọi nhiều lần dùng chung một lượt tải.
96	export function crowdLoad(): Promise<CrowdData | null> {
97	  if (pending) return pending;
98	  if (typeof location !== 'undefined' && new URLSearchParams(location.search).get('crowd') === 'off') return (pending = Promise.resolve(null));
99	  pending = (async () => {
100	    const C = CONFIG.people.crowd, ctl = new AbortController();
101	    let timer: ReturnType<typeof setTimeout> | undefined;
102	    const timeout = new Promise<never>((_, rej) => { timer = setTimeout(() => { ctl.abort(); rej(new Error(`quá ${C.loadTimeoutMs} ms`)); }, C.loadTimeoutMs); });
103	    const work = (async (): Promise<CrowdData> => {
104	      const base = import.meta.env.BASE_URL;
105	      const [rb, ri] = await Promise.all([fetch(base + C.bin, { signal: ctl.signal }), fetch(base + C.atlas, { signal: ctl.signal })]);
106	      if (!rb.ok || !ri.ok) throw new Error(`HTTP ${rb.status} / ${ri.status}`);
107	      const [buf, blob] = await Promise.all([rb.arrayBuffer(), ri.blob()]);
108	      const parsed = crowdParse(buf);
109	      const bmp = await createImageBitmap(blob);
110	      const atlas = new THREE.Texture(bmp);
111	      atlas.flipY = false; atlas.colorSpace = THREE.SRGBColorSpace; atlas.name = 'peopleCrowdAtlas'; atlas.needsUpdate = true;
112	      const anim = new THREE.DataTexture(parsed.animData as Uint16Array<ArrayBuffer>, parsed.animWidth, parsed.animHeight, THREE.RGBAFormat, THREE.HalfFloatType);
113	      anim.minFilter = anim.magFilter = THREE.NearestFilter; anim.generateMipmaps = false; anim.name = 'peopleCrowdAnim'; anim.needsUpdate = true;
114	      return { ...parsed, anim, atlas };
115	    })();
116	    work.catch(() => {}); timeout.catch(() => {});
117	    try {
118	      loaded = await Promise.race([work, timeout]);
119	    } catch (e) {
120	      console.warn('[people] không dùng được đám đông người thật, dùng hình khối:', e instanceof Error ? e.message : e);
121	      loaded = null;
122	    } finally { clearTimeout(timer); }
123	    return loaded;
124	  })();
125	  return pending;
126	}
