38	export function updateDragonPeople(dt: number, elapsed: number, cam: THREE.Camera): void {
39	  if (!dragon) return;
40	  const near = cam.position.distanceTo(CENTER) < D.hideDistance;
41	  if (near) stepPeople(dragon, dt, elapsed, true);
42	  dragon.group.visible = near && weatherFx.clear < 1;   // bão đã dọn hết thì bỏ luôn lệnh vẽ
43	}
