48	  const g = scene.getObjectByName(name), meshes: THREE.InstancedMesh[] = [];
49	  g?.traverse((o) => { if ((o as THREE.InstancedMesh).isInstancedMesh) meshes.push(o as THREE.InstancedMesh); });
50	  return { g, meshes, list: (g?.userData.people as People | undefined)?.list };
51	};
