54	  systems(): { name: string; count: number; visible: number; meshes: number; material: string; materialName: string; verts: number; colors: number; shirtKinds: number; instAttrs: boolean; groupVisible: boolean }[] {
55	    return PP_NAMES.map((name) => {
56	      const { g, meshes } = ppFind(name), m = meshes[0];
57	      if (!m) return null;
58	      const a = m.instanceMatrix.array, c = m.instanceColor?.array, geo = m.geometry, shirts = new Set<string>();
59	      let visible = 0;
60	      for (let i = 0; i < m.count; i++) { if (Math.abs(a[i * 16]) + Math.abs(a[i * 16 + 1]) + Math.abs(a[i * 16 + 2]) > 1e-9) visible++; if (c) shirts.add(`${c[i * 3].toFixed(3)},${c[i * 3 + 1].toFixed(3)},${c[i * 3 + 2].toFixed(3)}`); }
61	      const inst = (n: string) => !!(geo.getAttribute(n) as THREE.InstancedBufferAttribute)?.isInstancedBufferAttribute;
62	      const mat = m.material as THREE.Material;
63	      return { name, count: m.count, visible, meshes: meshes.length, material: mat.uuid, materialName: mat.name, verts: geo.getAttribute('position').count, colors: c ? c.length / 3 : 0, shirtKinds: shirts.size, instAttrs: inst('aVar') && inst('aPants'), groupVisible: g.visible };
64	    }).filter(Boolean);
65	  },
66	  /* Vị trí cục bộ (trong nhóm cầu) từng người, cao độ mặt lề tại đó, kiểu, scale, trục đứng (y của trục Y), hướng mặt (+X của hình) */
67	  positions(name: string): { i: number; x: number; y: number; z: number; ground: number; kind: string; scale: number; upY: number; fwd: number[] }[] {
68	    const { meshes, list } = ppFind(name), m = meshes[0], M = new THREE.Matrix4(), p = new THREE.Vector3(), q = new THREE.Quaternion(), s = new THREE.Vector3(), up = new THREE.Vector3(), fwd = new THREE.Vector3();
69	    if (!m || !list) return [];
70	    return list.map((w, i) => {
71	      m.getMatrixAt(i, M); M.decompose(p, q, s);
72	      up.set(0, 1, 0).applyQuaternion(q); fwd.set(1, 0, 0).applyQuaternion(q);
73	      return { i, x: p.x, y: p.y, z: p.z, ground: w.profile(w.axis === 'z' ? w.z : w.x), kind: w.kind ?? 'walk', scale: s.x, upY: up.y, fwd: fwd.toArray() };
74	    });
75	  }
