2	import { CONFIG } from '../config';
3	import { renderer, scene, camera } from './renderer';
4	import { composer } from './postprocessing';
5	import { water } from './water';
6	import { LIGHT_SETS, LightSet, applyLightSet, stepLights, pointLights, lightState } from './lights';
7	
8	/* =====================================================================
9	   BIÊN DỊCH TRƯỚC (D-018) — chạy một lần lúc màn hình chờ còn hiện, trước khung hình đầu.
10	   Nếu không, three biên dịch shader của một vật liệu lần đầu nó được vẽ (đồng bộ trên luồng chính) ⇒ giật khi:
11	   chuyển đêm lần đầu (composer vẽ vào render target ⇒ biến thể không tone mapping), bay tới công trình có `details` đang ẩn, mặt cắt Hầm…
12	   - renderer.compile() duyệt MỌI object (kể cả đang ẩn), nên không cần bật tạm `visible`.
13	   - Hai biến thể: vẽ thẳng ra canvas (ban ngày) và vào render target (composer ban đêm; cũng trùng biến thể phản chiếu mặt nước).
14	   - Upload sẵn mọi texture (atlas quảng cáo 2048², địa chất 4096×636…) để lần hiện đầu không phải tải lên GPU.
15	   - Vẽ composer một lần: biên dịch các pass bloom / output.
16	   - Bộ đèn (D-031, core/lights.ts: day / night / full): số đèn nằm trong program key nên mỗi bộ là một program khác của cùng vật liệu. Theo device.lightSets:
17	     · 'off' / 'bg': trước khung đầu chỉ bộ 'full', đúng như trước D-031 (số program, thời gian màn hình chờ không đổi); 'bg' hâm 'day' rồi 'night' sau khung đầu (warmLightSets).
18	     · 'sync' (test:perf): lặp cả ba bộ (biên dịch + vẽ thật), sẵn sàng ngay. Bản đầu D-031 dùng cách này cho mọi người: 174 → 490 program, màn hình chờ Intel Arc 10–16 s → 26–36 s.
19	     Lượt "mọi object hiện" không bật visible của đèn / nhóm pointLights: bộ đang xét quyết định đèn nào hiện. Xong thì về bộ ứng với trạng thái thật (stepLights).
20	   Biến thể vẽ bóng (MeshDepthMaterial) vẫn biên dịch lười khi vật đổ bóng vào khung bóng lần đầu (ít program, rẻ).
21	   ===================================================================== */
22	const wait = (ms: number) => new Promise<void>((ok) => setTimeout(ok, ms));
23	
24	/* Vẽ thật một lần với MỌI object tạm hiện (trừ đèn), không cắt theo khung nhìn, mọi level LOD, InstancedMesh rỗng có 1 instance:
25	   upload hình học lên GPU, biên dịch biến thể vẽ bóng (MeshDepthMaterial) và phần trình điều khiển biên dịch lười lúc vẽ lần đầu
26	   (đo GĐ1: không còn program mới nhưng lần đầu bay tới Thuận Phước / Hầm / Vòng quay vẫn khựng 3–5 s trên SwiftShader). Trả nguyên trạng ngay sau đó.
27	   Đèn và nhóm pointLights giữ nguyên visible: bộ đèn đang xét quyết định đèn nào hiện. */
28	function drawAll() {
29	  const saved: [THREE.Object3D, boolean, boolean][] = [], counts: [THREE.InstancedMesh, number][] = [], lods: THREE.LOD[] = [];
30	  scene.traverse((o) => {
31	    if ((o as THREE.Light).isLight || o === pointLights) return;
32	    saved.push([o, o.visible, o.frustumCulled]); o.visible = true; o.frustumCulled = false;
33	    const im = o as THREE.InstancedMesh; if (im.isInstancedMesh && im.count === 0) { counts.push([im, 0]); im.count = 1; }
34	    const lod = o as THREE.LOD; if (lod.isLOD && lod.autoUpdate) { lods.push(lod); lod.autoUpdate = false; }
35	  });
36	  renderer.render(scene, camera);
37	  composer.render(0);
38	  for (const [o, v, f] of saved) { o.visible = v; o.frustumCulled = f; }
39	  for (const [im, n] of counts) im.count = n;
40	  for (const lod of lods) lod.autoUpdate = true;
41	}
42	
43	export async function prewarm() {
44	  // Font chữ Việt: atlas quảng cáo vẽ lại khi font nạp xong — chờ trước để chỉ upload một lần (tối đa 3 s nếu không có mạng)
45	  if (document.fonts?.ready) await Promise.race([document.fonts.ready, wait(3000)]);
46	  const rt = renderer.getRenderTarget();
47	  const seen = new Set<THREE.Texture>();
48	  scene.traverse((o) => {
49	    const m = (o as THREE.Mesh).material;
50	    if (!m) return;
51	    for (const mat of Array.isArray(m) ? m : [m]) for (const v of Object.values(mat)) if ((v as THREE.Texture)?.isTexture && !seen.has(v as THREE.Texture)) { seen.add(v as THREE.Texture); renderer.initTexture(v as THREE.Texture); }
52	  });
53	  const sync = lightState.mode === 'sync';
54	  for (const set of sync ? LIGHT_SETS : ['full' as LightSet]) {
55	    applyLightSet(set);   // đèn ẩn không vào trạng thái đèn của compile / render (three gom đèn bằng traverseVisible)
56	    renderer.setRenderTarget(null);
57	    const canvasPass = renderer.compileAsync(scene, camera);
58	    renderer.setRenderTarget(rt);
59	    await canvasPass;
60	    renderer.setRenderTarget(composer.readBuffer);
61	    const rtPass = renderer.compileAsync(scene, camera);
62	    renderer.setRenderTarget(rt);
63	    await rtPass;
64	    drawAll();
65	    // three vẽ shadow map TRƯỚC khi cập nhật trạng thái đèn của khung (WebGLRenderer.render: shadowMap.render rồi mới setupLights)
66	    // ⇒ khung đầu có sun sau một khung night, lượt bóng mang trạng thái đèn night trong program key của MeshDepthMaterial (đo: +5 program).
67	    // Vẽ thêm một lần bộ day ngay sau night (không compile xen giữa, vì compile cũng đặt lại trạng thái đèn) để biên dịch sẵn các biến thể đó.
68	    if (set === 'night') { applyLightSet('day'); drawAll(); }
69	  }
70	  if (sync) lightState.ready.day = lightState.ready.night = true;
71	  stepLights();   // về bộ ứng với cường độ đèn thật (applyNight đã chạy trước prewarm)
72	  composer.render(0);   // một lần nữa với trạng thái thật (bloom/output pass đã biên dịch ở lần trên)
73	}
74	
75	/* =====================================================================
76	   BIÊN DỊCH NỀN HAI BỘ ĐÈN (D-031, chế độ 'bg') — gọi mỗi khung từ animate() ngay trước lượt vẽ thật; hâm xong thì trả về ngay (không cấp phát).
77	   - Cần KHR_parallel_shader_compile: trình duyệt biên dịch / link ngoài luồng chính, ta chỉ trả phần đồng bộ (tạo mã shader, gửi lệnh).
78	     Không có ⇒ mode 'off', ở 'full' mãi (program chưa xong sẽ chặn luồng chính lúc dùng lần đầu: không đáng).
79	   - Pha 0 (biên dịch): mỗi khung, trong ngân sách CONFIG.perf.lightWarmMs và khi còn ít hơn CONFIG.perf.lightWarmPrograms program đang dịch dở:
80	     renderer.compile() từng nhóm CHUNK object, hai biến thể canvas / render target như prewarm. Đo Intel Arc (ANGLE D3D11): "song song" chỉ một phần —
81	     để 2–4 program mới mỗi khung dồn lại thì tiến trình GPU chặn khung 100–600 ms; giữ ≤ 2 đang dịch thì khung dài nhất ≈ 0,1–0,2 s, đổi lại chậm (≈ 20–30 s mỗi bộ).
82	   - Không đụng tới đèn thật: compile vào một Scene giả (warm.scene) cùng fog / environment, traverseVisible chỉ trả đèn của bộ đang hâm
83	     (danh sách lấy một lần lúc bắt đầu bằng applyLightSet tạm rồi trả lại ngay trong cùng lời gọi). three giữ trạng thái đèn theo scene
84	     (renderStates.get(scene)) nên trạng thái đèn của cảnh thật — kể cả cái lượt bóng khung sau còn đọc lại — không đổi.
85	   - compile() đặt currentProgram của vật liệu sang program bộ đang hâm (có thể chưa link xong) và nối uniform đèn vào trạng thái của Scene giả.
86	     Vật liệu có ánh sáng: lightsStateVersion khác trạng thái thật ⇒ khung sau setProgram tự gọi getProgram (tra bảng theo key, nối lại uniform).
87	     Vật liệu không ánh sáng (Basic, ShaderMaterial lights=false…) không có kiểm đó ⇒ đặt needsUpdate để lượt vẽ sau tra lại đúng program
88	     (tra bảng, không biên dịch); không thì nó dùng program của bộ đang hâm, phải chờ link đồng bộ.
89	   - Không dùng promise của compileAsync: nó kiểm currentProgram.isReady() sau 10 ms, lúc đó khung thật đã đặt currentProgram về bộ đang dùng
90	     ⇒ báo xong sớm. Thay vào đó giữ các program mới tạo (renderer.info.programs tăng thêm) và kiểm isReady() mỗi khung.
91	   - Pha 2 (vẽ thật, drawChunk) khi mọi program của bộ đã isReady ⇒ lightState.ready[bộ] = true; stepLights chuyển sang được từ khung sau.
92	   - Object gỡ khỏi cảnh trong lúc hâm (parent = null) bị bỏ qua; object thêm vào sau lúc bắt đầu hâm không được hâm (biên dịch lười như trước D-031).
93	   ===================================================================== */
94	const CHUNK = 2, DRAW_CHUNK = 2;   // object mỗi lần compile / mỗi lần vẽ hâm: nhỏ để kiểm ngân sách thường xuyên (một object vẽ lần đầu có thể tốn ~0,1 s) (ước lượng)
95	type Ready = { isReady(): boolean };
96	type Clip = { mat: THREE.Material; end: number };   // nhóm object cùng kiểu cắt (clippingPlanes + clipIntersection), object [.., end)
97	type Warm = { objs: THREE.Object3D[]; clips: Clip[]; ci: number; sets: { set: LightSet; lights: THREE.Light[] }[]; si: number; i: number; from: number; to: number;
98	  pending: Ready[]; pi: number; phase: number; scene: THREE.Scene; proxy: THREE.Object3D; clipScene: THREE.Scene; clipMesh: THREE.Mesh; clipRT: THREE.WebGLRenderTarget;
99	  draw: THREE.Scene; kids: THREE.Object3D[]; saved: Uint8Array; rts: THREE.WebGLRenderTarget[] };
100	let warm: Warm | null = null, warmDone = false;
101	/* Còn đang hâm nền bộ đèn không (quality.update bỏ khung dài do biên dịch khỏi trung bình). Chế độ khác 'bg' không bao giờ hâm */
102	export const lightsWarming = () => lightState.mode === 'bg' && !warmDone;
103	
104	/* Số mặt phẳng cắt nằm trong program key (numClippingPlanes / numClipIntersection) nhưng compile() không tự đặt: nó dùng trạng thái cắt còn lại
105	   từ vật liệu vẽ sau cùng (WebGLClipping.setState chỉ chạy trong setProgram lúc vẽ). Vẽ sau cùng của khung thường là vật liệu bị mặt cắt Hầm cắt
106	   (4 mặt phẳng) ⇒ compile mọi vật liệu khác ra key sai (đo: +30 program biên dịch đồng bộ, khung 4,2 s ở lần chuyển 'day' đầu).
107	   Nên: xếp object theo kiểu cắt, trước mỗi nhóm vẽ một tam giác bằng vật liệu cùng kiểu cắt vào render target 1×1 để đặt trạng thái đó. */
108	function setClip(w: Warm, k: number) {
109	  const c = renderer.info.render.calls, t = renderer.info.render.triangles;
110	  w.clipMesh.material = w.clips[k].mat;
111	  renderer.setRenderTarget(w.clipRT); renderer.render(w.clipScene, camera);
112	  renderer.info.render.calls = c; renderer.info.render.triangles = t;   // không tính vào lệnh vẽ của khung (HUD, test)
113	}
114	
115	function warmInit(): Warm {
116	  const objs: THREE.Object3D[] = [], clipOf = (o: THREE.Object3D) => { const m = (o as THREE.Mesh).material; const x = (Array.isArray(m) ? m[0] : m) as THREE.Material;
117	    return renderer.localClippingEnabled && x.clippingPlanes?.length ? x : null; };
118	  const groups = new Map<string, { rep: THREE.Material | null; objs: THREE.Object3D[] }>(), planeIds = new Map<THREE.Plane[], number>();
119	  scene.traverse((o) => {
120	    if (!(o as THREE.Mesh).material) return;   // cả vật liệu không ánh sáng: chúng cũng tra lại program (theo trạng thái đèn đang có) mỗi lần đổi canvas ↔ render target
121	    const c = clipOf(o);
122	    if (c && !planeIds.has(c.clippingPlanes)) planeIds.set(c.clippingPlanes, planeIds.size);
123	    const key = c ? `${planeIds.get(c.clippingPlanes)}:${c.clipIntersection}` : '';
124	    if (!groups.has(key)) groups.set(key, { rep: c, objs: [] });
125	    groups.get(key).objs.push(o);
126	  });
127	  const clips: Clip[] = [];
128	  for (const g of groups.values()) {
129	    for (const o of g.objs) objs.push(o);
130	    clips.push({ mat: new THREE.MeshBasicMaterial(g.rep ? { clippingPlanes: g.rep.clippingPlanes, clipIntersection: g.rep.clipIntersection } : {}), end: objs.length });
131	  }
132	  const clipMesh = new THREE.Mesh(new THREE.BufferGeometry().setAttribute('position', new THREE.Float32BufferAttribute([0, 0, 0, 0, 0, 0, 0, 0, 0], 3)));
133	  clipMesh.frustumCulled = false;
134	  const clipScene = new THREE.Scene(); clipScene.add(clipMesh);
135	  const keep = lightState.set, sets: Warm['sets'] = [];
136	  for (const set of ['day', 'night'] as LightSet[]) {
137	    applyLightSet(set);
138	    const lights: THREE.Light[] = [];
139	    scene.traverseVisible((o) => { if ((o as THREE.Light).isLight) lights.push(o as THREE.Light); });
140	    sets.push({ set, lights });
141	  }
142	  applyLightSet(keep);   // cùng lời gọi, trước khung kế tiếp: không khung nào vẽ với bộ tạm
143	  const w: Warm = { objs, clips, ci: 0, sets, si: 0, i: 0, from: 0, to: 0, pending: [], pi: 0, scene: new THREE.Scene(), proxy: new THREE.Object3D(), clipScene, clipMesh, clipRT: new THREE.WebGLRenderTarget(1, 1),
144	    phase: 0, draw: new THREE.Scene(), kids: [], saved: new Uint8Array(DRAW_CHUNK + 16),
145	    rts: [new THREE.WebGLRenderTarget(1, 1, { type: THREE.HalfFloatType }), new THREE.WebGLRenderTarget(1, 1)] };   // định dạng như composer / phản chiếu nước
146	  w.draw.children = w.kids; w.draw.matrixWorldAutoUpdate = false;
147	  // Scene giả: three gom đèn bằng targetScene.traverseVisible ⇒ chỉ trả đèn của bộ đang hâm
148	  w.scene.traverseVisible = (cb: (o: THREE.Object3D) => void) => { const ls = w.sets[w.si].lights; for (let k = 0; k < ls.length; k++) cb(ls[k]); };
149	  // Nhóm giả: compile duyệt vật liệu bằng traverse (phẳng, object [from, to)); traverseVisible rỗng ⇒ không thêm đèn
150	  w.proxy.traverse = (cb: (o: THREE.Object3D) => void) => { for (let k = w.from; k < w.to; k++) if (w.objs[k].parent) cb(w.objs[k]); };
151	  w.proxy.traverseVisible = () => {};
152	  return w;
153	}
154	
155	/* Vẽ thật một nhóm object với một bộ đèn, ngoài màn hình (trước lượt vẽ thật của khung, cùng lời gọi). Cần vì program "xong" (isReady) mới là
156	   xong phần link: trình điều khiển D3D còn dịch tiếp lúc vẽ lần đầu với từng định dạng đích (đo Intel Arc, chưa có bước này: lần đầu sang 'night'
157	   khựng 0,7 s dù +0 program; lần đầu sang 'day' gần 1 s). Vẽ vào scene riêng (w.draw) có children = đèn của bộ + các object của nhóm:
158	   parent của object không đổi (matrixWorld đã tính ở khung trước, tắt matrixWorldAutoUpdate), trạng thái đèn của cảnh thật không bị đụng.
159	   Ba đích như khung thật: canvas (biến thể tone mapping; cắt kéo 1×1, khung thật xoá cả canvas ngay sau), render target 1×1 HalfFloat
160	   (định dạng của composer ban đêm), 1×1 RGBA8 (định dạng phản chiếu mặt nước). Lượt bóng (MeshDepthMaterial) chỉ vẽ ở đích đầu và chỉ khi
161	   khung thật cũng vẽ lại bóng ngay sau (autoUpdate): không thì shadow map đang dùng bị ghi đè bằng bóng của riêng nhóm này.
162	   Nước: bỏ qua onBeforeRender (không vẽ lại phản chiếu thật). */
163	function drawChunk(w: Warm, si: number, canvasOnly: boolean) {
164	  const kids = w.kids, ls = w.sets[si].lights, sv = w.saved, sm = renderer.shadowMap;
165	  kids.length = 0;
166	  for (let k = 0; k < ls.length; k++) { kids.push(ls[k]); sv[k] = ls[k].visible ? 1 : 0; ls[k].visible = true; }
167	  for (let k = w.from; k < w.to; k++) {
168	    const o = w.objs[k], im = o as THREE.InstancedMesh, j = ls.length + k - w.from;
169	    if (!o.parent) { sv[j] = 8; continue; }   // đã gỡ khỏi cảnh
170	    sv[j] = (o.visible ? 1 : 0) | (o.frustumCulled ? 2 : 0) | (im.isInstancedMesh && im.count === 0 ? 4 : 0);
171	    o.visible = true; o.frustumCulled = false; if (sv[j] & 4) im.count = 1;
172	    kids.push(o);
173	  }
174	  const ob = water.onBeforeRender, au = sm.autoUpdate, nu = sm.needsUpdate, c = renderer.info.render.calls, t = renderer.info.render.triangles;
175	  water.onBeforeRender = noop;
176	  w.draw.fog = scene.fog; w.draw.environment = scene.environment; w.draw.environmentRotation.copy(scene.environmentRotation);   // cùng key fog / envMap
177	  sm.autoUpdate = false; sm.needsUpdate = au;
178	  renderer.setRenderTarget(null); renderer.setScissorTest(true); renderer.setScissor(0, 0, 1, 1);
179	  renderer.render(w.draw, camera);
180	  renderer.setScissorTest(false); sm.needsUpdate = false;
181	  if (!canvasOnly) for (const rt of w.rts) { renderer.setRenderTarget(rt); renderer.render(w.draw, camera); }
182	  sm.autoUpdate = au; sm.needsUpdate = nu; water.onBeforeRender = ob;
183	  renderer.info.render.calls = c; renderer.info.render.triangles = t;   // không tính vào lệnh vẽ của khung (HUD, test)
184	  for (let k = 0; k < ls.length; k++) ls[k].visible = sv[k] === 1;
185	  for (let k = w.from; k < w.to; k++) {
186	    const o = w.objs[k], j = ls.length + k - w.from;
187	    if (sv[j] & 8) continue;
188	    o.visible = (sv[j] & 1) !== 0; o.frustumCulled = (sv[j] & 2) !== 0; if (sv[j] & 4) (o as THREE.InstancedMesh).count = 0;
189	  }
190	  kids.length = 0;
191	}
192	const noop = () => {};
193	/* Mỗi khung, trước lượt vẽ thật (sau quality.update: biết khung này có vẽ lại bóng không). Hai pha cho từng bộ day rồi night:
194	   compile (ngân sách, giới hạn program đang dịch) đến khi mọi program mới isReady → vẽ thật từng nhóm (ngân sách) ⇒ ready[bộ].
195	   Pha vẽ của night: mỗi nhóm vẽ night rồi vẽ day một lần (chỉ canvas): khung 'day' đầu tiên sau đêm, lượt bóng còn mang trạng thái đèn night
196	   (three vẽ bóng trước khi cập nhật đèn) ⇒ biến thể MeshDepthMaterial đó được biên dịch + vẽ sẵn ở đây. */
197	export function warmLightSets() {
198	  if (warmDone) return;
199	  if (lightState.mode !== 'bg') { warmDone = true; return; }
200	  if (!warm) {
201	    if (!renderer.extensions.has('KHR_parallel_shader_compile')) { lightState.mode = 'off'; warmDone = true; return; }
202	    warm = warmInit();
203	  }
204	  const w = warm, n = w.objs.length, t0 = performance.now(), rt = renderer.getRenderTarget(), set = w.sets[w.si].set;
205	  if (w.phase === 0) {   // biên dịch nền: giữ tối đa lightWarmPrograms program đang dịch dở (đo Intel Arc: dồn nhiều ⇒ khung 100–600 ms)
206	    while (w.pi < w.pending.length && w.pending[w.pi].isReady()) w.pi++;   // COMPLETION_STATUS_KHR: không chặn
207	    const progs = renderer.info.programs;
208	    w.scene.fog = scene.fog; w.scene.environment = scene.environment; w.scene.environmentRotation.copy(scene.environmentRotation);   // cùng key fog / envMap với cảnh thật
209	    let clipSet = false;   // khung thật vừa vẽ đã đổi trạng thái cắt ⇒ đặt lại ở lần compile đầu của mỗi lời gọi
210	    while (w.i < n && w.pending.length - w.pi < CONFIG.perf.lightWarmPrograms && performance.now() - t0 < CONFIG.perf.lightWarmMs) {
211	      while (w.i >= w.clips[w.ci].end) { w.ci++; clipSet = false; }
212	      if (!clipSet) { setClip(w, w.ci); clipSet = true; }
213	      w.from = w.i; w.to = Math.min(w.i + CHUNK, w.clips[w.ci].end);
214	      const before = progs.length;
215	      renderer.setRenderTarget(null); renderer.compile(w.proxy, camera, w.scene);
216	      renderer.setRenderTarget(composer.readBuffer); renderer.compile(w.proxy, camera, w.scene);
217	      for (let k = before; k < progs.length; k++) w.pending.push(progs[k] as unknown as Ready);
218	      for (let k = w.from; k < w.to; k++) {
219	        if (!w.objs[k].parent) continue;
220	        const m = (w.objs[k] as THREE.Mesh).material;
221	        if (Array.isArray(m)) for (const x of m) x.needsUpdate = true; else m.needsUpdate = true;
222	      }
223	      w.i = w.to;
224	    }
225	    renderer.setRenderTarget(rt);
226	    if (w.i < n || w.pi < w.pending.length) return;
227	    w.phase = 2; w.i = 0;   // mọi program của bộ đã link xong
228	    w.from = w.to = 0; drawChunk(w, w.si, true);   // nhóm rỗng: đặt trạng thái đèn của scene vẽ = bộ này (lượt bóng nhóm đầu đọc nó)
229	  }
230	  while (w.i < n && performance.now() - t0 < CONFIG.perf.lightWarmMs) {   // vẽ thật
231	    w.from = w.i; w.to = Math.min(w.i + DRAW_CHUNK, n);
232	    drawChunk(w, w.si, false);
233	    if (set === 'night') drawChunk(w, 0, true);   // sets[0] là day
234	    w.i = w.to;
235	  }
236	  renderer.setRenderTarget(rt);
237	  if (w.i < n) return;
238	  lightState.ready[set] = true;
239	  if (++w.si < w.sets.length) { w.phase = 0; w.i = 0; w.ci = 0; w.pending.length = 0; w.pi = 0; return; }
240	  w.clipRT.dispose(); w.clipMesh.geometry.dispose(); for (const c of w.clips) c.mat.dispose(); for (const r of w.rts) r.dispose();
241	  warm = null; warmDone = true;
242	}
