// SPIKE: nạp dữ liệu nướng, atlas, vật liệu skinning bằng texture (BatchedMesh / InstancedMesh)
import * as THREE from 'three';
const D = './data/';
const NB = 22;

export async function loadChar(k, lod, fps = 15) {
  const meta = await (await fetch(`${D}p${k}.json`)).json();
  const parts = {};
  for (const tag of ['main', 'alpha']) {
    const p = meta.lods[lod][tag]; const buf = await (await fetch(D + p.file)).arrayBuffer();
    const n = p.verts, t = p.tris; let o = 0;
    const take = (C, len) => { const a = new C(buf.slice(o, o + len * C.BYTES_PER_ELEMENT)); o += len * C.BYTES_PER_ELEMENT; return a; };
    const pos = take(Float32Array, n * 3), nrm = take(Float32Array, n * 3), uv = take(Float32Array, n * 2), bones = take(Uint8Array, n * 2), w = take(Float32Array, n), mat = take(Uint8Array, n), idx = take(Uint32Array, t * 3);
    parts[tag] = { n, t, pos, nrm, uv, bones, w, mat, idx };
  }
  const anim = new Uint16Array(await (await fetch(`${D}p${k}_anim${fps}.bin`)).arrayBuffer());
  return { k, meta, parts, anim, clips: fps === 15 ? meta.clips : meta.clips30, frames: anim.length / (NB * 12) };
}

// atlas: mỗi nhân vật một ô cell×cell; trong ô: body [0,.75]x[0,1], head [.75,1]x[.5,1], alpha [.75,1]x[0,.5] (theo uv, gốc dưới trái)
const REG = { 0: [0, 0, 0.75, 1], 1: [0.75, 0.5, 0.25, 0.5], 2: [0.75, 0, 0.25, 0.5] };
export async function buildAtlas(chars, cell, { png = false, quality = 0.8 } = {}) {
  const cols = Math.min(chars.length, 4), rows = Math.ceil(chars.length / cols);
  const cv = document.createElement('canvas'); cv.width = cols * cell; cv.height = rows * cell;
  const g = cv.getContext('2d'); g.imageSmoothingQuality = 'high';
  const cells = [];
  for (let i = 0; i < chars.length; i++) {
    const cx = (i % cols) * cell, cy = Math.floor(i / cols) * cell; cells.push([cx / cv.width, 1 - (cy + cell) / cv.height, cell / cv.width, cell / cv.height]);
    for (const m of [0, 1, 2]) {
      const img = await loadImg(`${D}${chars[i].meta.tex[m].file}`); const r = REG[m];
      g.drawImage(img, cx + r[0] * cell, cy + (1 - r[1] - r[3]) * cell, r[2] * cell, r[3] * cell);
    }
  }
  const blob = await new Promise((ok) => cv.toBlob(ok, png ? 'image/png' : 'image/jpeg', quality));
  // dùng đúng ảnh đã nén (JPEG có mất mát) làm texture
  const bmp = await createImageBitmap(blob, { imageOrientation: 'flipY' });
  const tex = new THREE.Texture(bmp); tex.flipY = false; tex.colorSpace = THREE.SRGBColorSpace; tex.anisotropy = 4; tex.needsUpdate = true;
  return { tex, bytes: blob.size, w: cv.width, h: cv.height, cells, canvas: cv };
}
const loadImg = (src) => new Promise((ok, err) => { const i = new Image(); i.onload = () => ok(i); i.onerror = err; i.src = src; });

// hình học theo nhân vật: uv đã chuyển sang atlas; alphaMode: 'drop' | 'opaque' | 'test'
export function charGeometry(ch, cellRect, alphaMode) {
  const ps = alphaMode === 'drop' ? [ch.parts.main] : [ch.parts.main, ch.parts.alpha];
  const n = ps.reduce((s, p) => s + p.n, 0), t = ps.reduce((s, p) => s + p.t, 0);
  const pos = new Float32Array(n * 3), nrm = new Float32Array(n * 3), uv = new Float32Array(n * 2), bones = new Uint8Array(n * 2), w = new Float32Array(n), idx = new Uint32Array(t * 3);
  let vo = 0, io = 0;
  for (const p of ps) {
    pos.set(p.pos, vo * 3); nrm.set(p.nrm, vo * 3); bones.set(p.bones, vo * 2); w.set(p.w, vo);
    for (let i = 0; i < p.n; i++) {
      const r = REG[p.mat[i]], u = p.uv[i * 2] - Math.floor(p.uv[i * 2]), v = p.uv[i * 2 + 1] - Math.floor(p.uv[i * 2 + 1]);
      uv[(vo + i) * 2] = cellRect[0] + (r[0] + u * r[2]) * cellRect[2]; uv[(vo + i) * 2 + 1] = cellRect[1] + (r[1] + v * r[3]) * cellRect[3];
    }
    for (let i = 0; i < p.t * 3; i++) idx[io + i] = p.idx[i] + vo;
    vo += p.n; io += p.t * 3;
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3)); geo.setAttribute('normal', new THREE.BufferAttribute(nrm, 3));
  geo.setAttribute('uv', new THREE.BufferAttribute(uv, 2)); geo.setAttribute('aBones', new THREE.BufferAttribute(bones, 2)); geo.setAttribute('aW', new THREE.BufferAttribute(w, 1));
  geo.setIndex(new THREE.BufferAttribute(idx, 1)); geo.computeBoundingBox(); geo.computeBoundingSphere();
  // mở rộng bao để chuyển động không bị cắt nhầm
  geo.boundingSphere.radius += 0.6;
  return geo;
}

// texture chuyển động gộp mọi nhân vật: mỗi hàng = 1 khung, 66 texel (22 xương x 3 hàng ma trận)
export function animTexture(chars) {
  const rows = chars.reduce((s, c) => s + c.frames, 0); const data = new Uint16Array(rows * NB * 12);
  let r = 0; const base = [];
  for (const c of chars) { data.set(c.anim, r * NB * 12); base.push(r); r += c.frames; }
  const tex = new THREE.DataTexture(data, NB * 3, rows, THREE.RGBAFormat, THREE.HalfFloatType); tex.needsUpdate = true;
  return { tex, base, bytes: data.byteLength, rows };
}

// dữ liệu 1 người: [hàng đầu đoạn, số khung (âm = không lặp), khung/giây, lệch pha (s)]
export function personData(chars, animBase, ci, clip, rateMul, phase) {
  const c = chars[ci].clips[clip];
  return [animBase[ci] + c.start, c.loop ? c.n : -c.n, c.rate * rateMul, phase];
}

const SKIN = /* glsl */`
uniform highp sampler2D uAnim; uniform float uTime;
#ifndef SP_INSTANCED
uniform highp sampler2D uPeople;
#else
attribute vec4 iData; attribute float iChar; attribute float aChar;
#endif
attribute vec2 aBones; attribute float aW;
vec4 spRow(int b, int j, int f0, int f1, float t) { return mix(texelFetch(uAnim, ivec2(b * 3 + j, f0), 0), texelFetch(uAnim, ivec2(b * 3 + j, f1), 0), t); }
`;
const SKIN_MAIN = /* glsl */`
#ifndef SP_INSTANCED
  int spId = int(batchId); int spSz = textureSize(uPeople, 0).x;
  vec4 pd = texelFetch(uPeople, ivec2(spId % spSz, spId / spSz), 0);
#else
  vec4 pd = iData;
#endif
  float spN = abs(pd.y); float spF = (uTime + pd.w) * pd.z;
  int f0, f1; float ft;
  if (pd.y > 0.0) { spF = mod(spF, spN); f0 = int(spF); f1 = f0 + 1; if (float(f1) >= spN) f1 = 0; ft = fract(spF); }
  else { spF = clamp(spF, 0.0, spN - 1.0); f0 = int(spF); f1 = min(f0 + 1, int(spN) - 1); ft = fract(spF); }
  f0 += int(pd.x); f1 += int(pd.x);
  int b0 = int(aBones.x + 0.5), b1 = int(aBones.y + 0.5); float w1 = 1.0 - aW;
  vec4 sr0 = spRow(b0, 0, f0, f1, ft) * aW + spRow(b1, 0, f0, f1, ft) * w1;
  vec4 sr1 = spRow(b0, 1, f0, f1, ft) * aW + spRow(b1, 1, f0, f1, ft) * w1;
  vec4 sr2 = spRow(b0, 2, f0, f1, ft) * aW + spRow(b1, 2, f0, f1, ft) * w1;
  vec3 objectNormal = vec3(dot(sr0.xyz, normal), dot(sr1.xyz, normal), dot(sr2.xyz, normal));
#ifdef USE_TANGENT
  vec3 objectTangent = vec3( tangent.xyz );
#endif
`;
export function crowdMaterial(atlasTex, animTex, peopleTex, { instanced = false, alphaTest = 0 } = {}) {
  const m = new THREE.MeshStandardMaterial({ map: atlasTex, roughness: 0.8, metalness: 0, alphaTest });
  const uniforms = { uAnim: { value: animTex }, uPeople: { value: peopleTex }, uTime: { value: 0 } };
  m.userData.uniforms = uniforms;
  m.onBeforeCompile = (sh) => {
    Object.assign(sh.uniforms, uniforms);
    sh.vertexShader = (instanced ? '#define SP_INSTANCED\n' : '') + sh.vertexShader
      .replace('#include <common>', '#include <common>\n' + SKIN)
      .replace('#include <beginnormal_vertex>', SKIN_MAIN)
      .replace('#include <begin_vertex>', `vec4 spP = vec4(position, 1.0); vec3 transformed = vec3(dot(sr0, spP), dot(sr1, spP), dot(sr2, spP));
#ifdef SP_INSTANCED
 if (abs(aChar - iChar) > 0.5) transformed = vec3(0.0);
#endif
`);
  };
  m.customProgramCacheKey = () => 'spcrowd' + (instanced ? 'I' : 'B');
  return m;
}

