	const geometryCount = this._geometryCount;
	const boundingSphere = this.boundingSphere;
	const active = this._active;

	boundingSphere.makeEmpty();
	for ( let i = 0; i < geometryCount; i ++ ) {

		if ( active[ i ] === false ) continue;

